# ------------------------------------------------------------
# 3. LOAD DATA AND TRAIN DEMONSTRATION MODELS
# ------------------------------------------------------------

PROJECT_DIR = Path(__file__).resolve().parent
DATA_FILE = PROJECT_DIR / "data" / "cnc_surface_roughness_data.csv"

FEATURES = ["fz", "ap", "Vc", "vb", "C"]
QUALITY_LABELS = ["Low", "Medium", "High"]


@st.cache_data
def load_dataset(file_path: str) -> pd.DataFrame:
    frame = pd.read_csv(file_path)
    return frame


if not DATA_FILE.exists():
    st.error(
        "Dataset not found. Expected file: "
        "data/cnc_surface_roughness_data.csv"
    )
    st.stop()

data = load_dataset(str(DATA_FILE))

required_columns = FEATURES + ["Ra", "Run"]
missing_columns = [col for col in required_columns if col not in data.columns]

if missing_columns:
    st.error(f"Dataset is missing required columns: {missing_columns}")
    st.stop()

ra_data = data.dropna(subset=["Ra"]).copy()
X_ra = ra_data[FEATURES]
y_ra = ra_data["Ra"]


@st.cache_resource
def fit_demo_models(dataset: pd.DataFrame):
    """
    Fit models on all available records for interactive demonstration.
    These fitted models are not used to claim held-out test performance.
    """
    usable = dataset.dropna(subset=["Ra"]).copy()
    X_quality = usable[FEATURES]
    y_surface = usable["Ra"]

    # Regression demonstration model
    regression_model = LinearRegression()
    regression_model.fit(X_quality, y_surface)

    # K-Means uses all rows because its inputs have no missing values
    cluster_scaler = StandardScaler()
    X_all_scaled = cluster_scaler.fit_transform(dataset[FEATURES])

    cluster_model = KMeans(
        n_clusters=3,
        random_state=42,
        n_init=10,
    )
    cluster_model.fit(X_all_scaled)

    # Relative quality labels are derived from measured Ra quantiles
    usable["Quality"] = pd.qcut(
        usable["Ra"],
        q=3,
        labels=QUALITY_LABELS,
    )

    tree_model = DecisionTreeClassifier(
        criterion="gini",
        max_depth=3,
        min_samples_leaf=2,
        random_state=42,
    )
    tree_model.fit(usable[FEATURES], usable["Quality"])

    return (
        regression_model,
        cluster_scaler,
        cluster_model,
        tree_model,
        usable,
    )


(
    regression_model,
    cluster_scaler,
    cluster_model,
    tree_model,
    classified_data,
) = fit_demo_models(data)


