def metric_card(label: str, value: str, note: str, icon: str, accent: str):
    st.markdown(
        f"""
        <div class="metric-card">
            <div class="metric-top">
                <span>{label}</span>
                <span class="metric-icon {accent}">{icon}</span>
            </div>
            <div class="metric-value">{value}</div>
            <div class="metric-note">{note}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )


def panel_header(title: str, subtitle: str = ""):
    st.markdown(
        f"""
        <div class="panel-title">{title}</div>
        <div class="panel-subtitle">{subtitle}</div>
        """,
        unsafe_allow_html=True,
    )


def input_parameter_form(key_prefix: str):
    """Render coded-factor inputs and return a one-row DataFrame."""
    with st.form(f"{key_prefix}_input_form"):
        st.caption(
            "Enter coded experimental factor levels, not physical units. "
            "The observed design includes levels from -1.682 to +1.682."
        )

        c1, c2, c3 = st.columns(3)
        c4, c5, _ = st.columns(3)

        with c1:
            fz = st.number_input(
                "Feed per tooth (fz)",
                min_value=-1.682,
                max_value=1.682,
                value=0.0,
                step=0.1,
                key=f"{key_prefix}_fz",
            )
        with c2:
            ap = st.number_input(
                "Depth of cut (ap)",
                min_value=-1.682,
                max_value=1.682,
                value=0.0,
                step=0.1,
                key=f"{key_prefix}_ap",
            )
        with c3:
            vc = st.number_input(
                "Cutting speed (Vc)",
                min_value=-1.682,
                max_value=1.682,
                value=0.0,
                step=0.1,
                key=f"{key_prefix}_vc",
            )
        with c4:
            vb = st.number_input(
                "Tool wear (vb)",
                min_value=-1.682,
                max_value=1.682,
                value=0.0,
                step=0.1,
                key=f"{key_prefix}_vb",
            )
        with c5:
            concentration = st.number_input(
                "Fluid concentration (C)",
                min_value=-1.682,
                max_value=1.682,
                value=0.0,
                step=0.1,
                key=f"{key_prefix}_c",
            )

        submitted = st.form_submit_button("Run analysis", use_container_width=True)

    row = pd.DataFrame(
        [[fz, ap, vc, vb, concentration]],
        columns=FEATURES,
    )
    return submitted, row


